function vida(r){
  // detalles derivados deterministas: familia y antigüedad, para que hablen de SU vida
  let h=0;for(const c of r.id)h=(h*33+c.charCodeAt(0))>>>0;
  const hijos=r.edad>=25?["sin hijos","con un hijo","con dos hijos","con tres hijos"][h%4]:"";
  const barrio=r.edad>=30&&(h>>3)%3===0?"de toda la vida en el barrio":"";
  return [hijos,barrio].filter(Boolean).join(", ");
}
