let pendScroll=false;const COLADOWN=new Set();
function scrollAbajo(el){
  COLADOWN.add(el);
  if(pendScroll)return;
  pendScroll=true;
  requestAnimationFrame(()=>{pendScroll=false;
    COLADOWN.forEach(e=>{e.scrollTop=1e9});COLADOWN.clear();});
}
function typewriter(el,txt){
  const host=el.closest("#resps,#mesa");
  const card=el.closest(".resp"),cv=card?.querySelector("canvas.px");
  const r=card&&RESBY[card.dataset.rid];
  let habla=null;
  if(cv&&r){card.classList.add("talk");let b=0;
    habla=setInterval(()=>retrato(cv,r.id,r.sexo,r.ocupacion,r.edad,(b=!b)),160);TW.add(habla);}
  const fin=()=>{if(habla){clearInterval(habla);TW.delete(habla);card.classList.remove("talk");
    retrato(cv,r.id,r.sexo,r.ocupacion,r.edad);}};
  el.classList.remove("thinking");el.textContent="";
  let i=0;const paso=Math.max(1,Math.round(txt.length/60));
  const iv=setInterval(()=>{
    i+=paso;el.textContent=txt.slice(0,i);
    if(host)scrollAbajo(host);
    if(i>=txt.length){clearInterval(iv);TW.delete(iv);fin();}
  },28);TW.add(iv);
}
