  // misma poda que __rl: sin esto el Map crecía sin tope en instancias calientes
  for (const [k, v] of globalThis.__cupo) if (v.dia !== hoy) globalThis.__cupo.delete(k);
  if (globalThis.__cupo.size > 50) {
